CREATE TOPIC `ptah_ydb_repl/events`; CREATE TABLE `ptah_ydb_repl/rows` (id Int64 NOT NULL, PRIMARY KEY(id));CREATE TRANSFER `ptah_ydb_repl/ingest` FROM `ptah_ydb_repl/events` TO `ptah_ydb_repl/rows` USING ($msg) -> { RETURN [<|id:Unwrap(CAST($msg._offset AS Int64))|>]; } WITH (FLUSH_INTERVAL=Interval('PT1S'));ALTER TRANSFER `ptah_ydb_repl/ingest` SET USING ($msg) -> { RETURN [<|id:Unwrap(CAST($msg._offset AS Int64))+1l|>]; }, SET (BATCH_SIZE_BYTES=4096,FLUSH_INTERVAL=Interval('PT2S'));